from app.core.resources import display_rows

"""Admission Documents endpoints and their PostgreSQL queries."""

from fastapi import APIRouter, Depends, HTTPException, Query, Request

from app.core import sql_queries as sql
from app.core.resources import staff_only
from app.core.security import require

from .schemas import CreateRequest, UpdateRequest
from .service import Service

TABLE = "admission_documents"
router = APIRouter(prefix="/admission-documents", tags=["Admission Documents"])


# --- PostgreSQL queries for this screen (generated by tools/generate_module_sql.py from the
# live table definitions; regenerate after schema migrations). Values are bound as %(name)s
# parameters, never formatted into the text; app.core.sql_queries runs these statements and
# keeps custom fields (record_extras) with each record. Table names resolve through the
# connection's search_path (EDUNEXA_DB_SCHEMA).

LIST_SQL = """
SELECT t.code,
       t.application_code,
       t.document_type_code,
       t.revision,
       t.is_current,
       t.storage_key,
       t.original_filename,
       t.mime_type,
       t.size_bytes,
       t.sha256,
       t.issued_on,
       t.expires_on,
       t.uploaded_by_user_code,
       t.received_at,
       t.received_by_employee_code,
       t.status,
       t.original_sighted,
       t.original_sighted_by_code,
       t.original_sighted_at,
       t.reviewed_by_employee_code,
       t.reviewed_at,
       t.review_notes,
       t.waiver_reason,
       x.data AS extras
FROM admission_documents AS t
LEFT JOIN record_extras AS x
  ON x.table_name = 'admission_documents' AND x.record_code = t.code
ORDER BY t.code
"""

GET_SQL = """
SELECT t.code,
       t.application_code,
       t.document_type_code,
       t.revision,
       t.is_current,
       t.storage_key,
       t.original_filename,
       t.mime_type,
       t.size_bytes,
       t.sha256,
       t.issued_on,
       t.expires_on,
       t.uploaded_by_user_code,
       t.received_at,
       t.received_by_employee_code,
       t.status,
       t.original_sighted,
       t.original_sighted_by_code,
       t.original_sighted_at,
       t.reviewed_by_employee_code,
       t.reviewed_at,
       t.review_notes,
       t.waiver_reason,
       x.data AS extras
FROM admission_documents AS t
LEFT JOIN record_extras AS x
  ON x.table_name = 'admission_documents' AND x.record_code = t.code
WHERE t.code = %(code)s
"""

INSERT_SQL = """
INSERT INTO admission_documents (
    code,
    application_code,
    document_type_code,
    revision,
    is_current,
    storage_key,
    original_filename,
    mime_type,
    size_bytes,
    sha256,
    issued_on,
    expires_on,
    uploaded_by_user_code,
    received_at,
    received_by_employee_code,
    status,
    original_sighted,
    original_sighted_by_code,
    original_sighted_at,
    reviewed_by_employee_code,
    reviewed_at,
    review_notes,
    waiver_reason
)
VALUES (
    %(code)s,
    %(application_code)s,
    %(document_type_code)s,
    COALESCE(%(revision)s, 1),
    COALESCE(%(is_current)s, true),
    %(storage_key)s,
    %(original_filename)s,
    %(mime_type)s,
    %(size_bytes)s,
    %(sha256)s,
    %(issued_on)s,
    %(expires_on)s,
    %(uploaded_by_user_code)s,
    COALESCE(%(received_at)s, CURRENT_TIMESTAMP),
    %(received_by_employee_code)s,
    %(status)s,
    COALESCE(%(original_sighted)s, false),
    %(original_sighted_by_code)s,
    %(original_sighted_at)s,
    %(reviewed_by_employee_code)s,
    %(reviewed_at)s,
    %(review_notes)s,
    %(waiver_reason)s
)
"""

UPDATE_SQL = """
UPDATE admission_documents
SET application_code = %(application_code)s,
    document_type_code = %(document_type_code)s,
    revision = %(revision)s,
    is_current = %(is_current)s,
    storage_key = %(storage_key)s,
    original_filename = %(original_filename)s,
    mime_type = %(mime_type)s,
    size_bytes = %(size_bytes)s,
    sha256 = %(sha256)s,
    issued_on = %(issued_on)s,
    expires_on = %(expires_on)s,
    uploaded_by_user_code = %(uploaded_by_user_code)s,
    received_at = %(received_at)s,
    received_by_employee_code = %(received_by_employee_code)s,
    status = %(status)s,
    original_sighted = %(original_sighted)s,
    original_sighted_by_code = %(original_sighted_by_code)s,
    original_sighted_at = %(original_sighted_at)s,
    reviewed_by_employee_code = %(reviewed_by_employee_code)s,
    reviewed_at = %(reviewed_at)s,
    review_notes = %(review_notes)s,
    waiver_reason = %(waiver_reason)s
WHERE code = %(code)s
"""

DELETE_SQL = """
DELETE FROM admission_documents
WHERE code = %(code)s
"""

REFERENCED_BY_SQL = """
SELECT CASE
    WHEN EXISTS (SELECT 1 FROM document_verification_events WHERE admission_document_code = %(code)s) THEN 'document_verification_events'
    WHEN EXISTS (SELECT 1 FROM student_document_links WHERE admission_document_code = %(code)s) THEN 'student_document_links'
END AS referenced_by
"""
# --- end of generated SQL


def query_list(data):
    return [row for row in sql.fetch_all(data, TABLE, LIST_SQL) if not row.get("deleted_at")]


def query_get(data, code):
    record = sql.fetch_one(data, TABLE, GET_SQL, code)
    if record is None:
        raise HTTPException(404, "Record not found")
    return record


def query_save(data, record):
    return sql.save(data, TABLE, record, INSERT_SQL, UPDATE_SQL)


def query_delete(data, code):
    sql.delete(data, TABLE, DELETE_SQL, code)


def query_referenced_by(data, code):
    return sql.referenced_by(data, TABLE, REFERENCED_BY_SQL, code)


class Queries:
    table = TABLE
    list = staticmethod(query_list)
    get = staticmethod(query_get)
    save = staticmethod(query_save)
    delete = staticmethod(query_delete)
    referenced_by = staticmethod(query_referenced_by)


service = Service(Queries())


@router.get("")
def list_records(
    request: Request,
    offset: int = Query(0, ge=0),
    limit: int = Query(50, ge=1, le=200),
    user=Depends(require(TABLE, "view")),
):
    staff_only(user)
    data = request.app.state.store.snapshot()
    records = display_rows(data, TABLE, query_list(data))
    return {
        "items": records[offset : offset + limit],
        "total": len(records),
        "offset": offset,
        "limit": limit,
    }


@router.get("/{code}")
def get_record(code: str, request: Request, user=Depends(require(TABLE, "view"))):
    staff_only(user)
    return query_get(request.app.state.store.snapshot(), code)


@router.post("", status_code=201)
def create_record(
    body: CreateRequest, request: Request, user=Depends(require(TABLE, "create"))
):
    staff_only(user)
    with request.app.state.store.transaction() as data:
        return service.create(
            data, body.model_dump(mode="json", exclude_unset=True), user["code"]
        )


@router.patch("/{code}")
def update_record(
    code: str,
    body: UpdateRequest,
    request: Request,
    user=Depends(require(TABLE, "edit")),
):
    staff_only(user)
    with request.app.state.store.transaction() as data:
        return service.update(
            data, code, body.model_dump(mode="json", exclude_unset=True), user["code"]
        )


@router.delete("/{code}", status_code=204)
def delete_record(code: str, request: Request, user=Depends(require(TABLE, "delete"))):
    staff_only(user)
    from app.modules.documents.files.api import delete_file
    delete_file("admission-document", code, request, user)
